t.script:
(function() {
    function initOTP() {
        var container = document.querySelector('.auth_otp_inputs');
        if (!container) return;

        var inputs = Array.prototype.slice.call(container.querySelectorAll('.auth_otp_digit_input'));
        var hiddenInput = document.getElementById('otp_token_hidden');
        var form = document.querySelector('.auth_otp_form');
        var resendBtn = document.getElementById('btn_resend_otp');
        var cooldownContainer = document.getElementById('cooldown_container');
        var timerText = document.getElementById('cooldown_timer_text');

        function syncToken() {
            if (hiddenInput) {
                hiddenInput.value = inputs.map(function(i) { return i.value; }).join('');
            }
        }

        if (inputs.length > 0) {
            setTimeout(function() { inputs[0].focus(); }, 150);
        }

        inputs.forEach(function(input, idx) {
            input.addEventListener('keydown', function(e) {
                if (e.key === 'Backspace') {
                    if (!input.value && idx > 0) {
                        inputs[idx - 1].focus();
                        inputs[idx - 1].value = '';
                    } else {
                        input.value = '';
                    }
                    syncToken();
                    e.preventDefault();
                } else if (e.key === 'ArrowLeft' && idx > 0) {
                    inputs[idx - 1].focus();
                } else if (e.key === 'ArrowRight' && idx < inputs.length - 1) {
                    inputs[idx + 1].focus();
                }
            });

            input.addEventListener('input', function(e) {
                var clean = input.value.replace(/[^0-9]/g, '');
                input.value = clean ? clean.charAt(clean.length - 1) : '';

                if (input.value && idx < inputs.length - 1) {
                    inputs[idx + 1].focus();
                }
                syncToken();

                var allFilled = inputs.every(function(inp) { return inp.value.length === 1; });
                if (allFilled && form) {
                    form.submit();
                }
            });

            input.addEventListener('paste', function(e) {
                e.preventDefault();
                var data = (e.clipboardData || window.clipboardData).getData('text') || '';
                var digits = data.replace(/[^0-9]/g, '').split('');

                if (digits.length > 0) {
                    digits.forEach(function(d, dIdx) {
                        if (idx + dIdx < inputs.length) {
                            inputs[idx + dIdx].value = d;
                        }
                    });

                    var nextFocus = Math.min(idx + digits.length, inputs.length - 1);
                    inputs[nextFocus].focus();
                    syncToken();

                    var allFilled = inputs.every(function(inp) { return inp.value.length === 1; });
                    if (allFilled && form) {
                        form.submit();
                    }
                }
            });
        });

        // Live Countdown Timer
        if (cooldownContainer) {
            var secs = parseInt(cooldownContainer.getAttribute('data-remaining') || '0', 10);
            if (secs > 0) {
                var timer = setInterval(function() {
                    secs -= 1;
                    if (timerText) {
                        timerText.textContent = secs;
                    }
                    if (secs <= 0) {
                        clearInterval(timer);
                        if (resendBtn) {
                            resendBtn.removeAttribute('disabled');
                            resendBtn.classList.remove('disabled');
                        }
                        cooldownContainer.innerHTML = '<span class="text-success small"><i class="fa fa-check-circle mr-1"></i>You can request a new code now.</span>';
                    }
                }, 1000);
            }
        }
    }

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        initOTP();
    } else {
        document.addEventListener('DOMContentLoaded', initOTP);
    }
})();
